const raw = $input.first().json;
let data = raw;
if (raw.body !== undefined) {
  let rawBody = raw.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try { data = JSON.parse(rawBody); } catch(e) { data = raw; }
  } else if (typeof rawBody === 'object') { data = rawBody; }
}

const task_id      = data.task_id      || 'unknown';
const improvePrompt = data.improve_prompt || data.userRequest || '';
const existingCode  = data.existing_server_js || '';
const existingRoutes = data.existing_routes || [];
const existingStores = data.existing_stores || {};
const existingVersion = data.existing_version || '1.0';

// Sécurité : limiter la taille
if (existingCode.length > 40000) {
  return [{ json: { error: "Code trop volumineux", valid: false } }];
}
if (!improvePrompt) {
  return [{ json: { error: "Prompt d amélioration manquant", valid: false } }];
}

// Analyser le prompt pour identifier le type de changements
const p = improvePrompt.toLowerCase();

const changes = {
  // Backend
  add_delete:       p.includes('supprimer') || p.includes('delete') || p.includes('suppression'),
  add_put:          p.includes('modifier') || p.includes('editer') || p.includes('mettre à jour'),
  add_validation:   p.includes('validation') || p.includes('valider') || p.includes('positif'),
  add_status:       p.includes('statut') || p.includes('status') || p.includes('état'),
  add_search:       p.includes('recherche') || p.includes('filtrer') || p.includes('filter'),
  add_pagination:   p.includes('pagination') || p.includes('page') || p.includes('limit'),
  // Frontend
  show_delete_btn:  p.includes('supprimer') || p.includes('bouton suppr'),
  show_title_fields: p.includes('affiche') || p.includes('afficher') || p.includes('titre'),
  add_dropdown:     p.includes('liste déroulante') || p.includes('dropdown') || p.includes('sélection'),
  add_form_fields:  p.includes('champ') || p.includes('formulaire') || p.includes('ajoute un champ'),
};

// Calculer la version cible
const [major, minor] = existingVersion.split('.').map(Number);
const isMajor = p.includes('base de données') || p.includes('authentification') || p.includes('auth');
const nextVersion = isMajor ? (major + 1) + '.0' : major + '.' + (minor + 1);

// Générer les instructions structurées pour l'Architect
const backendInstructions = [];
const frontendInstructions = [];

if (changes.add_delete) {
  existingRoutes.filter(r => r.method === 'GET' && r.path !== '/health').forEach(r => {
    const base = r.path;
    backendInstructions.push('AJOUTER DELETE ' + base + '/:id — supprimer un élément par id');
    frontendInstructions.push('AJOUTER bouton Supprimer sur chaque item de la liste ' + base.replace('/', ''));
  });
}
if (changes.add_put) {
  existingRoutes.filter(r => r.method === 'GET' && r.path !== '/health').forEach(r => {
    backendInstructions.push('AJOUTER PUT ' + r.path + '/:id — modifier un élément');
  });
}
if (changes.add_validation) {
  backendInstructions.push('AJOUTER validation : tous les champs de type number doivent être > 0');
  backendInstructions.push('AJOUTER validation GPS : latitude entre -90 et 90, longitude entre -180 et 180');
}
// Détecter demandes de validation enum
var wantsEnum = p.includes('enum') || p.includes('valeurs acceptées') || p.includes('liste de valeurs') || p.includes('statut valide') || p.includes('priorité valide');
if (wantsEnum) {
  backendInstructions.push('AJOUTER validation : vérifier que les champs statut et priorite ont des valeurs parmi les valeurs acceptées définies dans la spec');
}
if (changes.add_status) {
  Object.keys(existingStores).forEach(res => {
    backendInstructions.push('AJOUTER champ status au store ' + res + ' (valeurs: en_attente, acceptee, refusee, livree)');
  });
}
if (changes.add_search) {
  existingRoutes.filter(r => r.method === 'GET' && r.path !== '/health').forEach(r => {
    backendInstructions.push('AJOUTER query params ?search= sur GET ' + r.path);
  });
}
if (changes.show_title_fields) {
  frontendInstructions.push('AFFICHER les 2 premiers champs descriptifs dans le titre de chaque item (ex: ville_de_depart → ville_d_arrivee)');
}
if (changes.add_dropdown) {
  // Détecter dynamiquement les champs FK depuis les stores existants
  var fkFields = [];
  Object.values(existingStores).forEach(function(store) {
    (store.required_fields || []).forEach(function(f) {
      if (f.endsWith('_id') && f !== 'id') {
        var refStore = f.replace(/_id$/, 's');
        fkFields.push({ field: f, route: '/' + refStore });
      }
    });
  });
  if (fkFields.length > 0) {
    fkFields.forEach(function(fk) {
      frontendInstructions.push('AJOUTER liste déroulante pour le champ ' + fk.field + ' qui charge GET ' + fk.route + ' dynamiquement');
    });
  } else {
    frontendInstructions.push('AJOUTER liste déroulante sur les champs _id qui chargent la ressource liée dynamiquement');
  }
}

// Si aucun changement détecté — utiliser le prompt brut
if (backendInstructions.length === 0 && frontendInstructions.length === 0) {
  backendInstructions.push('APPLIQUER : ' + improvePrompt);
  frontendInstructions.push('APPLIQUER : ' + improvePrompt);
}

return [{
  json: {
    task_id,
    improve_prompt:        improvePrompt,
    existing_version:      existingVersion,
    next_version:          nextVersion,
    existing_routes:       existingRoutes,
    existing_stores:       existingStores,
    existing_server_js:    existingCode,
    backend_instructions:  backendInstructions,
    frontend_instructions: frontendInstructions,
    changes_detected:      changes,
    changelog:             'v' + existingVersion + ' → v' + nextVersion + ' : ' + improvePrompt.substring(0, 100)
  }
}];
